<?php use SwimlogStandalone\PlanMatch as PM;$mf=$planMatchForm; ?>
<section class="calendar-panel workout-page" aria-labelledby="plan-match-title"><div class="workout-page-heading"><h2 id="plan-match-title">Match recorded workout</h2><a class="control" href="<?php echo esc_url($mf['context']['url']); ?>">Back to calendar</a></div>
<h3><?php echo esc_html($mf['title']); ?></h3><p>Planned: <?php echo esc_html($mf['planned_date'].' · '.($mf['type']==='pool'?'Pool swim':'Open-water swim').' · '.$mf['planned_distance']); ?>.</p>
<p>Choose the swim that completed this plan, then confirm. Matching marks the plan completed and locks its linked prescription. Existing matches remain unchanged.</p>
<form class="match-date-filter date-jump" method="get"><?php foreach(array('match_plan'=>$mf['id'],'date'=>$mf['context']['date'],'view'=>$mf['context']['view'])as$key=>$value): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>"><?php endforeach; ?><label for="match-recorded-date">Recorded date</label><input id="match-recorded-date" type="date" name="recorded_date" min="1900-01-01" max="2199-12-31" required value="<?php echo esc_attr($mf['recorded_date']); ?>"><button class="control">Show swims</button></form>
<?php if($mf['error']): ?><p role="alert"><?php echo esc_html($mf['error']->get_error_message()); ?></p><p><a href="<?php echo esc_url(PM::url($mf,$mf['page'])); ?>">Reload match form</a></p><?php endif; ?>
<?php if(!$mf['candidates']): ?><p class="match-empty">No available swims on this page. Swims already matched to a plan are omitted. Try another recorded date or page.</p><?php else: ?>
<form class="plan-match-editor" method="post" action="/?action=plan_match"><?php foreach(array('plan_id'=>$mf['id'],'nonce'=>wp_create_nonce('swimlog_plan_match_'.$mf['id']),'revision'=>$mf['revision'],'date'=>$mf['context']['date'],'view'=>$mf['context']['view'],'recorded_date'=>$mf['recorded_date'],'match_page'=>$mf['page'])as$key=>$value): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($value); ?>"><?php endforeach; ?>
<fieldset class="match-candidates"><legend>Select one recorded swim</legend><?php foreach($mf['candidates']as$candidate): ?><div class="match-candidate" data-candidate-id="<?php echo esc_attr($candidate['id']); ?>"><label><input type="radio" name="recorded_choice" value="<?php echo esc_attr($candidate['choice']); ?>" required <?php checked($mf['choice'],$candidate['choice']); ?>><span><strong><?php echo esc_html($candidate['start'].' · '.$candidate['distance']); ?></strong><span>Elapsed: <?php echo esc_html($candidate['elapsed']); ?> · Recorded moving time: <?php echo esc_html($candidate['moving']); ?></span><?php if($candidate['suggested']): ?><span class="match-suggestion">Suggested by Swim Log for this plan’s date</span><?php endif; ?></span></label><a href="<?php echo esc_url($mf['context']['url'].'&workout='.$candidate['id']); ?>" target="_blank" rel="noopener">View swim #<?php echo esc_html($candidate['id']); ?> <span class="sr-only">in a new tab</span></a></div><?php endforeach; ?></fieldset>
<div class="plan-actions"><button>Confirm match</button><a class="control" href="<?php echo esc_url($mf['context']['url']); ?>">Cancel</a></div></form><?php endif; ?>
<nav class="log-pagination" aria-label="Recorded swim pages"><?php if($mf['page']>1): ?><a class="control" href="<?php echo esc_url(PM::url($mf,$mf['page']-1)); ?>">Previous swims</a><?php endif; ?><span>Page <?php echo esc_html($mf['page']); ?> of <?php echo esc_html($mf['pages']); ?> · Already matched swims are omitted</span><?php if($mf['page']<$mf['pages']): ?><a class="control" href="<?php echo esc_url(PM::url($mf,$mf['page']+1)); ?>">Next swims</a><?php endif; ?></nav></section>
